      "सेवाएं देने के लिए हम एकत्र कर सकते हैं: खाता जानकारी (नाम, ईमेल, फोन), प्रोफ़ाइल डेटा (बायो, फोटो, स्थान), ऐप उपयोग डेटा, पुश नोटिफिकेशन के लिए डिवाइस आईडी, और आपकी सामग्री (पोस्ट, लिस्टिंग, संदेश)। पूर्ण विवरण के लिए गोपनीयता नीति देखें।",
