    delete_info_sec_2_content:
      "खाता हटाने पर हम हटाते हैं: आपकी प्रोफ़ाइल और खाता विवरण, पोस्ट और टिप्पणियां, लिस्टिंग और चैट इतिहास, और सर्वर पर संग्रहीत प्राथमिकताएं। कानूनी आवश्यकता (जैसे लेनदेन रिकॉर्ड) के लिए कुछ डेटा रखा जा सकता है।",
    delete_info_sec_3_title: "खाता कैसे हटाएं",
    delete_info_sec_3_content:
      "ऐप खोलें → प्रोफ़ाइल → सेटिंग्स। \"डेंजर ज़ोन\" में \"खाता हटाएं\" पर टैप करें। ऑन-स्क्रीन चरणों का पालन करें और पुष्टि के लिए DELETE टाइप करें। आप सहायता से संपर्क करके भी खाता हटाने का अनुरोध कर सकते हैं।",
