    // Farming Tips
    tip_1_title: "मृदा परीक्षण",
    tip_1_description:
      "पोषक तत्वों के स्तर, पीएच और कार्बनिक पदार्थों को समझने के लिए नियमित मृदा परीक्षण करें। इससे आपको सही मात्रा में उर्वरक डालने में मदद मिलती है।",
    tip_1_details:
      "साल में कम से कम एक बार, रोपण सीजन से पहले अपनी मिट्टी का परीक्षण करें। अपने खेत में कई स्थानों से नमूने एकत्र करें और उन्हें प्रमाणित प्रयोगशाला में भेजें। परिणामों के आधार पर, पीएच को चूने या सल्फर के साथ समायोजित करें और आवश्यकतानुसार विशिष्ट पोषक तत्व डालें।",
