    tip_2_description:
      "मिट्टी की संरचना, जल धारण क्षमता और पोषक तत्वों की उपलब्धता में सुधार के लिए खाद, गोबर की खाद या हरी खाद डालें।",
    tip_2_details:
      "सालाना प्रति एकड़ 5-10 टन अच्छी तरह से सड़ी हुई जैविक खाद डालें। इसे मिट्टी की ऊपरी 6-8 इंच परत में मिलाएं। कार्बनिक पदार्थ मिट्टी में हवा का संचार और जल निकासी को बेहतर बनाता है और फसलों को धीरे-धीरे पोषक तत्व प्रदान करता है।",
