    tip_3_details:
      "3-4 साल का चक्र अपनाएं। उदाहरण: फलियां → अनाज → तिलहन → सब्जियां। फलियां नाइट्रोजन जमा करती हैं, अनाज इसका उपयोग करते हैं, और विभिन्न फसलें कीट चक्र को तोड़ती हैं।",
