      "भंडारण से पहले अनाज को सुरक्षित नमी स्तर (आमतौर पर 10-12%) तक सुखाएं। भंडारण क्षेत्रों को साफ और पवित्र करें। हर्मेटिक (हवाबंद) बैग या धातु के डिब्बे कीटों और मोल्ड के विकास को रोकते हैं। खराब होने से बचाने के लिए अपने स्टॉक की नियमित जांच करें।",
