    tip_28_details:
      "जिप्सम (कैओलिन सल्फेट) मिट्टी के कणों को एक साथ लाने में मदद करता है, जिससे जड़ों के लिए जगह बनती है। अम्लीय मिट्टी के लिए, चूने का उपयोग करें। यह जड़ों को मिट्टी में गहराई तक जाने और पोषक तत्वों को बेहतर ढंग से अवशोषित करने में मदद करता है।",
