    tip_1_details:
      "वर्षातून किमान एकदा, पेरणीच्या हंगामापूर्वी तुमच्या मातीची चाचणी करा. तुमच्या शेतातील अनेक ठिकाणांवरून नमुने गोळा करा आणि त्यांना प्रमाणित प्रयोगशाळेत पाठवा. निकालांच्या आधारे, चुना किंवा गंधकने पीएच समायोजित करा आणि गरजेनुसार विशिष्ट पोषक तत्वे जोडा.",
