      "जनावरांपासून मोफत खत मिळते. कोंबड्या कीटक खातात. शेळ्या तण खातात. यामुळे एक पूरक चक्र तयार होते, जिथे शेतातील कचरा जनावरांना आणि जनावरांचे खत शेताला मिळते, ज्यामुळे नफा वाढतो.",
    tip_42_category: "soil",
    tip_42_season: "all",
    tip_42_difficulty: "advanced",

    tip_43_title: "मातीचे सौरकरण (Soil Solarization)",
    tip_43_description:
      "उन्हाळ्यात ओलसर जमिनीत पारदर्शक प्लास्टिक शीट अंथरून मातीतील रोगजंतू, सूत्रकृमी आणि तणाचे बी नष्ट करा.",
    tip_43_details:
      "मे-जूनच्या कडक उन्हात 4-6 आठवडे हे करा. सूर्याची उष्णता प्लास्टिकखाली अडकते आणि मातीचे तापमान वाढवते. रसायनांशिवाय माती 'निर्जंतुक' करण्याचा हा सुरक्षित, नैसर्गिक मार्ग आहे.",
    tip_43_category: "pest",
    tip_43_season: "summer",
    tip_43_difficulty: "advanced",

    tip_44_title: "रोगप्रतिकारक वाण",
    tip_44_description:
      "बुरशीनाशके आणि उपचारांची गरज कमी करण्यासाठी, शक्य असेल तेव्हा स्थानिक रोगांना प्रतिकार करणाऱ्या पिकांच्या जाती निवडा.",
    tip_44_details:
      "बियाणे खरेदी करताना माहिती तपासा. उदाहरणार्थ, टोमॅटोच्या काही जाती मर रोगाला प्रतिकार करतात. प्रतिकारक जाती रोगाचा प्रादुर्भाव असूनही चांगले उत्पादन देतात, ज्यामुळे खर्च वाचतो आणि जोखीम कमी होते.",
    tip_44_category: "crop",
    tip_44_season: "planting",
    tip_44_difficulty: "beginner",

    tip_45_title: "बाजारभाव आणि वेळ",
    tip_45_description:
      "बाजारभाव आणि ट्रेंडवर लक्ष ठेवा. नफा जास्तीत जास्त मिळवण्यासाठी काढणी आणि विक्रीची वेळ साधा.",
    tip_45_details:
      "केवळ उत्पादनावर लक्ष देऊ नका; विपणनावरही लक्ष द्या. जर भाव कमी असतील आणि साठवणूक शक्य असेल तर थांबा. सणवार किंवा लग्नसराईत मागणी जास्त असते. मध्यस्थांना टाळून थेट ग्राहकांना किंवा आठवडी बाजारात माल विकण्याचा प्रयत्न करा.",
    tip_45_category: "crop",
    tip_45_season: "harvest",
    tip_45_difficulty: "intermediate",

