    // Who We Are Section
    who_we_are_title: "आम्ही कोण आहोत",
    who_we_are_p1:
      "ऍग्रोपियर ची स्थापना भारतीय शेतीला स्मार्ट डिजिटल उपायांनी परिवर्तन करण्याच्या उद्देशाने करण्यात आली. आम्ही प्रत्येक शेतकऱ्यापर्यंत विश्वासार्ह बाजारभाव, हवामान अंदाज, तज्ञांचे मार्गदर्शन आणि आधुनिक शेती साधने पोहोचवण्याचे काम करतो.",
    who_we_are_p2:
      "आमचे प्लॅटफॉर्म आधुनिक तंत्रज्ञान आणि पारंपरिक कृषी ज्ञान यांचा संगम घडवतो, ज्यामुळे ग्रामीण शेतकरी आणि डिजिटल इनोव्हेशन यांच्यातील अंतर कमी होते. डेटा-आधारित निर्णयक्षमता शेतकऱ्यांची उत्पादकता वाढवते, धोके कमी करते आणि नफा जास्त करते असा आमचा विश्वास आहे.",
    who_we_are_p3:
      "रिअल-टाइम बाजारभावांपासून AI-आधारित कीड ओळखपर्यंत, कम्युनिटी फोरमपासून स्मार्ट सिंचन व्यवस्थापनापर्यंत — ऍग्रोपियर हा तुमचा संपूर्ण शेती साथीदार आहे.",
    // Vision
    vision_title: "आमचे व्हिजन",
